 async function importFile(file){
  if(!file||importRef.current)return;
  if(file.size>50*1024*1024){notify('O JSON deve ter no máximo 50 MB.',true);return;}
  const controller=new AbortController();importRef.current=controller;
  const cinematic=page==='portal',currentUpload=accountSync.beginUpload();setCinematicImport(cinematic);setImportProgress(cinematic?0:1);setImportPhase('Preparando importação');setIsLoading(true);
  const sequence=cinematic?startSummoning({signal:controller.signal,onFrame:({percent,message})=>{setImportProgress(percent);setImportPhase(message);}}):null;
  const realProgress=(percent,message)=>{if(!cinematic){setImportProgress(previous=>Math.max(previous,percent));if(message)setImportPhase(message);}};
  try{
   const imported=await importAccountFile(file,{signal:controller.signal,onProgress:({percent,message})=>{if(!controller.signal.aborted){realProgress(percent,message);}}});
   if(!currentUpload()||controller.signal.aborted)return;
   realProgress(90,'Preparando as áreas de times');
   await new Promise(resolve=>requestAnimationFrame(resolve));
   // Resolve lazy destination code before mounting the imported account.
   await Promise.all([import('./components/PveHub'),import('./components/SiegeCentral'),...(cinematic?[import('./components/AccountDashboard')]:[])]);
   if(!currentUpload()||controller.signal.aborted)return;
   realProgress(94,'Montando times e salvando inventário');
   await new Promise(resolve=>requestAnimationFrame(resolve));
   const installed=await installAccount(imported,{destination:cinematic?'dashboard':null,beforeCommit:sequence?.completed,shouldInstall:()=>currentUpload()&&!controller.signal.aborted,onProgress:percent=>realProgress(percent)});
   if(installed===false)return;
   if(!readFlag(ONBOARDING_KEY)){writeFlag(ONBOARDING_PENDING_KEY);setTourRequested(true);}
   realProgress(99,'Finalizando interface');
   await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
   if(!cinematic){setImportProgress(100);setImportPhase('Importação concluída');}
   if(currentUpload())void accountSync.save(imported);
   reportEvent('swex_imported');
   notify(`${imported.name}: ${imported.units.length} monstros e ${imported.runes.length} runas · ${imported.accountPresets.length} decks (${imported.accountPresets.filter(p=>isPve(p.gameMode)).length} PvE).`);
  }catch(e){if(e.name!=='AbortError'){reportEvent('swex_failed');notify(e.message,true);}}
  finally{
   sequence?.cancel();
   // Keep the overlay through the React commit and the first painted account UI.
   if(!controller.signal.aborted)await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
   if(importRef.current===controller){importRef.current=null;setIsLoading(false);setCinematicImport(false);if(fileRef.current)fileRef.current.value='';}
  }
 }

